
<template>
  <div class="flex flex-col gap-6">
    <h3 class="text-xl font-semibold">Select Time Slot</h3>
    
    <div v-if="!store.selectedDate" class="text-gray-500">
      Please select a date in the previous step.
    </div>

    <div v-else class="grid grid-cols-1 gap-4">
      <div 
        v-for="schedule in availableSchedules" 
        :key="schedule.name"
        class="border rounded-lg p-4 flex justify-between items-center transition-all cursor-pointer"
        :class="[
          isFull(schedule) ? 'opacity-50 cursor-not-allowed bg-gray-50' : '',
          store.selectedSchedule === schedule.name ? 'border-gray-900 ring-1 ring-gray-900 bg-gray-50' : 'hover:border-gray-400 bg-white'
        ]"
        @click="selectSchedule(schedule)"
      >
        <div>
           <div class="text-lg font-bold">
            {{ formatTime(schedule.start_time) }} - {{ formatTime(schedule.end_time) }}
           </div>
           <div class="text-sm text-gray-500 max-w-md">
             Capacity: {{ schedule.enrolled_count }} / {{ schedule.max_capacity }}
           </div>
        </div>
        
        <div v-if="isFull(schedule)" class="text-red-500 font-medium">
          Full
        </div>
        <div v-else-if="store.selectedSchedule === schedule.name" class="text-green-600 font-bold">
          Selected
        </div>
      </div>
       <div v-if="availableSchedules.length === 0" class="text-gray-500">
        No schedules available for this date.
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { useRegistrationStore } from '@/stores/registration'

const store = useRegistrationStore()

const availableSchedules = computed(() => {
  if (!store.schedulesResource.data || !store.selectedDate) return []
  return store.schedulesResource.data.filter((s: any) => s.date === store.selectedDate)
})

function isFull(schedule: any) {
    if (schedule.max_capacity === 0) return false
    // Check if adding current participants would exceed capacity
    // Actually, capacity check should use current enrolled ONLY here for 'Full' status display.
    // Validation happens on submit.
    return schedule.enrolled_count >= schedule.max_capacity
}

function selectSchedule(schedule: any) {
  if (isFull(schedule)) return
  store.selectedSchedule = schedule.name
}

function formatTime(timeStr: string) {
  if (!timeStr) return ''
  // Assume timeStr is HH:mm:ss
  const [hours, minutes] = timeStr.split(':')
  return `${hours}:${minutes}`
}
</script>
