
<template>
  <div class="flex flex-col gap-6">
    <h3 class="text-xl font-semibold">Confirm Registration</h3>

    <!-- Event Summary -->
    <div class="bg-gray-50 p-4 rounded-lg flex flex-col gap-2">
       <h4 class="font-bold text-lg">{{ store.event?.title }}</h4>
       <div v-if="dateStr" class="text-gray-700">
          <span class="font-medium">Date:</span> {{ dateStr }}
       </div>
       <div v-if="timeStr" class="text-gray-700">
          <span class="font-medium">Time:</span> {{ timeStr }}
       </div>
    </div>

    <!-- User Summary -->
    <div class="border p-4 rounded-lg">
       <h4 class="font-bold mb-2">My Information</h4>
       <div class="text-sm">
         <p><span class="font-medium">Name:</span> {{ store.user.full_name }}</p>
         <p><span class="font-medium">Email:</span> {{ store.user.email }}</p>
         <p><span class="font-medium">Phone:</span> {{ store.user.phone }}</p>
       </div>
    </div>

     <!-- Participants Summary -->
     <div class="border p-4 rounded-lg">
       <h4 class="font-bold mb-2">Participants ({{ store.participants.length }})</h4>
       <ul class="space-y-3">
         <li v-for="(p, i) in store.participants" :key="i" class="text-sm border-b pb-2 last:border-0 last:pb-0">
            <p><span class="font-medium">Name:</span> {{ p.full_name }}</p>
            <p class="text-gray-500">{{ p.email }}</p>
         </li>
       </ul>
     </div>

     <!-- Captcha Widget -->
     <div id="turnstile-widget" class="min-h-[65px]"></div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { useRegistrationStore } from '@/stores/registration'
import { createResource } from 'frappe-ui'

const store = useRegistrationStore()

const dateStr = computed(() => {
    if (!store.selectedDate) return ''
    return new Intl.DateTimeFormat('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }).format(new Date(store.selectedDate))
})

const timeStr = computed(() => {
    if (!store.selectedSchedule || !store.schedulesResource.data) return ''
    const schedule = store.schedulesResource.data.find((s: any) => s.name === store.selectedSchedule)
    if (!schedule) return ''
    return `${schedule.start_time} - ${schedule.end_time}`
})

// Turnstile / Captcha
const settings = createResource({
    url: 'ticketed_event.api.get_settings',
    auto: true,
    onSuccess(data: any) {
        if (data.turnstile_site_key) {
            initTurnstile(data.turnstile_site_key)
        }
    }
})

function initTurnstile(siteKey: string) {
    if (document.getElementById('turnstile-script')) {
        renderWidget(siteKey)
        return
    }

    const script = document.createElement('script')
    script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?onload=onloadTurnstileCallback'
    script.id = 'turnstile-script'
    script.async = true
    script.defer = true
    document.head.appendChild(script)

    window.onloadTurnstileCallback = () => {
        renderWidget(siteKey)
    }
}

function renderWidget(siteKey: string) {
    if (!window.turnstile) return
    window.turnstile.render('#turnstile-widget', {
        sitekey: siteKey,
        callback: function(token: string) {
            store.captchaToken = token
        },
    })
}
</script>

<script lang="ts">
declare global {
  interface Window {
    turnstile: any;
    onloadTurnstileCallback: any;
  }
}
</script>
