
<template>
  <div class="max-w-3xl mx-auto p-6" v-if="registration.data">
    <div class="text-center mb-8">
      <h1 class="text-3xl font-bold text-green-600 mb-2">Registration Confirmed!</h1>
      <p class="text-gray-600">Thank you for registering. Here are your tickets.</p>
    </div>

    <!-- Event Info -->
    <div class="bg-gray-100 p-6 rounded-lg mb-8 text-center">
        <h2 class="text-2xl font-bold mb-2">{{ registration.data.event }}</h2>
        <div class="text-lg">
             {{ formatDate(registration.data.schedule) }}
        </div>
        <div class="mt-4 text-sm text-gray-500">
            Registration ID: {{ registration.data.name }}
        </div>
    </div>

    <!-- Tickets / Participants -->
    <div class="grid gap-6 md:grid-cols-2">
      <div 
        v-for="p in participants" 
        :key="p.name"
        class="border-2 border-dashed border-gray-300 rounded-xl p-6 flex flex-col items-center bg-white"
      >
        <div class="mb-4">
             <!-- QR Code Generator or Image -->
             <!-- Using a simple reliable QR code API for demo or relying on backend generated image url if exists -->
             <!-- For now, assuming we render a QR code on frontend using a library or just placeholder if no library -->
             <img 
                :src="`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${p.qr_code_id}`" 
                alt="QR Code" 
                class="w-32 h-32"
             />
        </div>
        <div class="text-center">
             <h3 class="font-bold text-lg">{{ p.full_name }}</h3>
             <p class="text-sm text-gray-500">{{ p.email }}</p>
             <p class="text-xs text-gray-400 mt-2 font-mono">{{ p.qr_code_id }}</p>
        </div>
        <div v-if="p.checked_in" class="mt-4 px-3 py-1 bg-green-100 text-green-800 rounded-full text-xs font-bold">
            CHECKED IN
        </div>
      </div>
    </div>

    <div class="mt-12 text-center">
      <Button @click="router.push('/')">Back to Home</Button>
    </div>
  </div>
  <div v-else class="flex h-screen items-center justify-center">
    <LoadingIndicator />
  </div>
</template>

<script setup lang="ts">
import { useRoute, useRouter } from 'vue-router'
import { createResource, Button, LoadingIndicator } from 'frappe-ui'
import { computed } from 'vue'

const route = useRoute()
const router = useRouter()
const registrationId = route.params.id as string

const registrationDetails = createResource({
  url: 'ticketed_event.api.get_registration_details',
  params: {
    name: registrationId
  },
  auto: true
})

const registration = computed(() => ({
    data: registrationDetails.data?.registration
}))

const participants = computed(() => registrationDetails.data?.participants || [])

function formatDate(dateStr: string) {
    if(!dateStr) return ''
    return new Date(dateStr).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
}
</script>
