<template>
  <div class="relative h-screen w-full overflow-hidden bg-gray-50">
    <!-- Loading State -->
    <div v-if="events.loading" class="flex h-full items-center justify-center">
      <LoadingIndicator />
    </div>

    <!-- Error/No Events -->
    <div v-else-if="!events.data || events.data.length === 0" class="flex h-full items-center justify-center flex-col gap-4 text-center p-6">
        <h1 class="text-2xl font-bold text-gray-500">No Active Events</h1>
        <p class="text-gray-400">Please check back later.</p>
    </div>

    <!-- Landing Content -->
    <div v-else class="h-full relative flex flex-col">
        <!-- Background Image (Placeholder or Event Image) -->
        <div class="absolute inset-0 z-0">
             <img 
                :src="events.data[0].image || 'https://placehold.co/600x800'" 
                class="w-full h-full object-cover"
                alt="Event Background"
            />
            <div class="absolute inset-0 bg-black/10"></div>
        </div>

        <!-- Content Overlay -->
        <div class="relative z-10 flex flex-col h-full justify-between p-6 pb-12">
            <!-- Header (Search/Menu from design - using simplified placeholders) -->
            <div class="flex justify-between items-center pt-4">
                 <div class="h-10 w-10 bg-white/70 backdrop-blur rounded-full flex items-center justify-center shadow-sm">
                    <span class="text-xl">􀯶</span>
                 </div>
                 <div class="h-10 w-full max-w-[200px] bg-white/70 backdrop-blur rounded-full mx-2 shadow-sm"></div>
            </div>

            <!-- Bottom Section -->
            <div class="flex flex-col gap-6">
                 <div>
                     <h1 class="text-[32px] leading-tight font-normal text-white mb-2" style="font-family: 'Inter', sans-serif;">
                        {{ events.data[0].title }}
                     </h1>
                 </div>
                 
                 <button 
                    @click="openRegistration"
                    class="w-full py-4 bg-black text-white rounded-full text-lg font-medium shadow-lg hover:bg-gray-900 transition-colors"
                >
                    Register Now
                 </button>
            </div>
        </div>
    </div>

    <!-- Bottom Sheet / Wizard -->
    <div v-if="showWizard" class="fixed inset-0 z-20 flex items-end justify-center pointer-events-none">
        <!-- Backdrop -->
        <div class="absolute inset-0 bg-black/40 pointer-events-auto transition-opacity" @click="closeRegistration"></div>
        
        <!-- Sheet Content -->
        <div class="bg-white w-full max-w-lg rounded-t-[30px] shadow-2xl overflow-hidden pointer-events-auto transform transition-transform duration-300 max-h-[90vh] flex flex-col">
             <!-- Drag Handle -->
             <div class="w-full flex justify-center py-3 bg-white" @click="closeRegistration">
                 <div class="w-12 h-1.5 bg-gray-300 rounded-full"></div>
             </div>

             <!-- Wizard -->
             <div class="flex-1 overflow-y-auto bg-white">
                 <RegistrationWizard 
                    v-if="events.data && events.data[0]"
                    :event-id="events.data[0].name" 
                    @close="closeRegistration"
                 />
             </div>
        </div>
    </div>

  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import { createListResource, createResource, LoadingIndicator } from 'frappe-ui'
import RegistrationWizard from './RegistrationWizard.vue'

const showWizard = ref(false)

const events = createResource({
  url: 'ticketed_event.api.get_published_events',
  auto: true
})

function openRegistration() {
    showWizard.value = true
}

function closeRegistration() {
    showWizard.value = false
}
</script>
